// GENERATED by scripts/sync-shared.mjs from hotelclash/src/game — do not edit here.
import {
  newGame,
  applyAction,
  applyActionInPlace,
  replay,
  hashState,
  stateFromLegacy,
} from '../engine/index.js';

// Client side of the server-authoritative game.
//
// The browser runs the shared engine locally (instant feedback, works offline)
// and records every accepted action. For signed-in players the log is
// uploaded to the API, which replays it with the same engine; the server's
// result is authoritative. If the server disagrees (cheating, an engine
// update, another device), the store adopts the server state and re-applies
// any newer local actions on top of it.
//
// Guests play fully offline; their log is kept so that, if they create an
// account within MAX_ADOPT_AGE_MS, the server can verify and adopt it.

const STORAGE_KEY = 'hotelClash.engine.v1';
const LEGACY_STATE_KEY = 'hotelClashGameState';
const LEGACY_ACHIEVEMENTS_KEY = 'hotelClash_savedAchievements';
const SYNC_CHUNK = 2000;
const GUEST_LOG_CAP = 20000;
const MAX_ADOPT_AGE_MS = 29 * 24 * 60 * 60 * 1000;
const POLL_MS = 1000;
const MAX_POLLS = 30;

const randomSeed = () => {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
};

function readJson(storage, key) {
  try {
    const raw = storage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

export class GameStore {
  /**
   * @param {object} deps
   * @param {Storage} deps.storage   localStorage-like
   * @param {object}  deps.api       { getSession, createSession, sync, getBatch, sessionFromSave }
   * @param {() => number} [deps.now]
   */
  constructor({ storage, api, now = () => Date.now() }) {
    this.storage = storage;
    this.api = api;
    this.now = now;
    this.data = null; // persisted record, see _fresh()
    this.listeners = new Set();
    this.syncing = null;
    this.lastSyncError = null;
    this.corrections = 0; // times the server's verified state replaced local progress
  }

  // ------------------------------------------------------------ persistence

  _fresh({ mode, state, origin, seed = null, startedAt = null, userId = null, sessionId = null, seq = 0 }) {
    return {
      v: 1,
      mode, // 'guest' | 'account'
      userId,
      sessionId,
      origin, // 'new' (adoptable log) | 'legacy' | 'server' | 'compacted'
      seed,
      startedAt,
      confirmed: { seq, state }, // last server-verified (or initial) state
      pending: [], // actions after confirmed.seq
      current: state, // confirmed + pending, what the UI shows
    };
  }

  persist() {
    try {
      this.storage.setItem(STORAGE_KEY, JSON.stringify(this.data));
    } catch {
      // Storage full: keep playing in memory; the next successful sync still works.
    }
  }

  subscribe(fn) {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  _changed() {
    for (const fn of this.listeners) fn(this.data.current);
  }

  get state() {
    return this.data && this.data.current;
  }

  get pendingCount() {
    return this.data ? this.data.pending.length : 0;
  }

  get confirmedSeq() {
    return this.data ? this.data.confirmed.seq : 0;
  }

  get mode() {
    return this.data && this.data.mode;
  }

  // ------------------------------------------------------------ setup

  /** Local-only game (guests, or signed-in players before the first sync). */
  _startGuest({ hotelName, hotelType } = {}) {
    const t = this.now();
    const legacy = readJson(this.storage, LEGACY_STATE_KEY);
    if (legacy && typeof legacy === 'object' && legacy.rooms) {
      // A pre-engine local game: convert it (unranked for guests).
      const state = stateFromLegacy(legacy, {
        seed: randomSeed(),
        t,
        hotelName,
        hotelType,
        achievements: this._legacyAchievements(),
        limits: { maxMoney: Number.MAX_SAFE_INTEGER, maxCredits: Number.MAX_SAFE_INTEGER },
      });
      this.data = this._fresh({ mode: 'guest', state, origin: 'legacy' });
    } else {
      const seed = randomSeed();
      const state = newGame({ seed, hotelName, hotelType, t });
      this.data = this._fresh({ mode: 'guest', state, origin: 'new', seed, startedAt: t });
    }
  }

  _legacyAchievements() {
    const list = readJson(this.storage, LEGACY_ACHIEVEMENTS_KEY);
    return Array.isArray(list) ? list.filter((a) => a && a.unlocked).map((a) => a.id) : [];
  }

  _fromServer(session, userId) {
    this.data = this._fresh({
      mode: 'account',
      state: session.state,
      origin: 'server',
      userId,
      sessionId: session.id,
      seq: session.seq,
    });
  }

  /**
   * Load the saved game and, for signed-in players, attach it to their server
   * session (creating one if needed). Safe to call again when coming online.
   */
  async init({ userId = null, hotelName, hotelType, online = true } = {}) {
    if (!this.data) this.data = readJson(this.storage, STORAGE_KEY);
    if (this.data && this.data.v !== 1) this.data = null;

    if (!userId) {
      if (!this.data || this.data.mode !== 'guest') this._startGuest({ hotelName, hotelType });
      this.persist();
      this._changed();
      return;
    }

    const ownAccount = this.data && this.data.mode === 'account' && this.data.userId === userId;
    if (!online) {
      // Offline: continue whatever we have locally; attach when back online.
      if (!this.data || (this.data.mode === 'account' && !ownAccount)) this._startGuest({ hotelName, hotelType });
      this.persist();
      this._changed();
      return;
    }

    const server = await this.api.getSession(); // null when the player has none
    if (ownAccount && server && server.id === this.data.sessionId) {
      if (server.seq !== this.data.confirmed.seq) this._rebase(server, { batchApplied: false });
    } else if (server) {
      // Another device or a restored save: the server's session wins.
      this._fromServer(server, userId);
    } else {
      this.data = await this._createServerSession(userId, { hotelName, hotelType });
    }
    this.persist();
    this._changed();
    await this.sync();
  }

  /** First session for this account: adopt the guest game if we can verify it. */
  async _createServerSession(userId, { hotelName, hotelType }) {
    const local = this.data && this.data.mode === 'guest' ? this.data : null;
    const adoptable =
      local &&
      local.origin === 'new' &&
      local.confirmed.seq === 0 &&
      local.pending.length <= GUEST_LOG_CAP &&
      this.now() - local.startedAt < MAX_ADOPT_AGE_MS;

    if (adoptable) {
      const initial = local.confirmed.state;
      const session = await this.api.createSession({
        hotelName: initial.hotelName,
        hotelType: initial.hotelType,
        adopt: { seed: local.seed, startedAt: local.startedAt },
      });
      const record = this._fresh({ mode: 'account', state: session.state, origin: 'server', userId, sessionId: session.id });
      record.pending = local.pending; // already numbered from 1
      record.current = local.current;
      return record;
    }

    let legacy = null;
    if (local) legacy = { state: local.current, achievements: local.current.achievements };
    else {
      const old = readJson(this.storage, LEGACY_STATE_KEY);
      if (old && old.rooms) legacy = { state: old, achievements: this._legacyAchievements() };
    }
    let session;
    try {
      session = await this.api.createSession({ hotelName, hotelType, ...(legacy ? { legacy } : {}) });
    } catch (err) {
      // Already imported once for this account: start fresh instead.
      if (legacy && err && err.response && err.response.status === 409) session = await this.api.createSession({ hotelName, hotelType });
      else throw err;
    }
    return this._fresh({ mode: 'account', state: session.state, origin: 'server', userId, sessionId: session.id, seq: session.seq });
  }

  // ------------------------------------------------------------ gameplay

  /**
   * Apply an action locally. Accepted actions are recorded for the server.
   * @returns {{ ok: boolean, error?: string, effects: object[] }}
   */
  dispatch(type, payload = {}) {
    const d = this.data;
    const seq = d.confirmed.seq + d.pending.length + 1;
    const action = { ...payload, seq, t: this.now(), type };
    const result = applyAction(d.current, action);
    if (result.ok) {
      d.current = result.state;
      d.pending.push(action);
      if (d.mode === 'guest' && d.pending.length > GUEST_LOG_CAP) {
        // Too long to keep for adoption; keep playing from a snapshot.
        d.confirmed = { seq: d.confirmed.seq + d.pending.length, state: d.current };
        d.pending = [];
        d.origin = 'compacted';
      }
      this._changed();
    }
    return result;
  }

  /**
   * Apply several actions as one update (e.g. "set all Deluxe rooms to $120").
   * Same result and same recorded actions as calling dispatch() for each, but
   * the state is copied once instead of once per action, and listeners fire once.
   * @param {{ type: string, [key: string]: any }[]} list
   * @returns {{ ok: boolean, error?: string, effects: object[] }[]} one result per action
   */
  dispatchMany(list) {
    const d = this.data;
    const S = structuredClone(d.current);
    const results = [];
    let accepted = 0;
    for (const { type, ...payload } of list) {
      const action = { ...payload, seq: d.confirmed.seq + d.pending.length + 1, t: this.now(), type };
      const result = applyActionInPlace(S, action);
      if (result.ok) {
        d.pending.push(action);
        accepted += 1;
      }
      results.push(result);
    }
    if (accepted) {
      d.current = S;
      if (d.mode === 'guest' && d.pending.length > GUEST_LOG_CAP) {
        d.confirmed = { seq: d.confirmed.seq + d.pending.length, state: d.current };
        d.pending = [];
        d.origin = 'compacted';
      }
      this._changed();
    }
    return results;
  }

  /** Start over (signed-in players get a new server session). */
  async newGame({ hotelName, hotelType } = {}) {
    if (this.data && this.data.mode === 'account') {
      // Let the server see every action first: it carries the coin wallet over.
      await this.sync().catch(() => false);
      const session = await this.api.createSession({ hotelName, hotelType });
      this._fromServer(session, this.data.userId);
    } else {
      this.storage.removeItem(LEGACY_STATE_KEY);
      this.data = null;
      this._startGuest({ hotelName, hotelType });
    }
    this.persist();
    this._changed();
  }

  /** Continue from a verified cloud save (replaces the current session). */
  async restoreSave(saveId) {
    await this.sync().catch(() => false);
    const session = await this.api.sessionFromSave(saveId);
    this._fromServer(session, this.data.userId);
    this.persist();
    this._changed();
  }

  /** Guests only: load a locally saved snapshot (not adoptable afterwards). */
  loadLocalSnapshot(state) {
    if (this.data.mode !== 'guest') throw new Error('Signed-in players restore saves from the cloud');
    this.data = this._fresh({ mode: 'guest', state, origin: 'compacted' });
    this.persist();
    this._changed();
  }

  // ------------------------------------------------------------ sync

  /**
   * Adopt a server state. `batchApplied` means the server applied our upload
   * (possibly with corrections), so those actions are dropped; otherwise all
   * unconfirmed actions are re-applied on top of the server state.
   */
  _rebase(server, { batchApplied, appliedUpTo = server.seq }) {
    const d = this.data;
    const leftover = batchApplied ? d.pending.filter((a) => a.seq > appliedUpTo) : d.pending;
    const renumbered = leftover.map((a, i) => ({ ...a, seq: server.seq + 1 + i }));
    const { state, rejected } = replay(server.state, renumbered);
    const dropped = new Set(rejected.map((r) => r.seq));
    let next = server.seq + 1;
    d.pending = renumbered.filter((a) => !dropped.has(a.seq)).map((a) => ({ ...a, seq: next++ }));
    d.confirmed = { seq: server.seq, state: server.state };
    if (dropped.size || !batchApplied) this.corrections += 1;
    d.current = dropped.size ? replay(server.state, d.pending).state : state;
    if (server.id) d.sessionId = server.id;
  }

  /** Upload pending actions. Resolves to true when everything is confirmed. */
  sync() {
    if (this.syncing) return this.syncing;
    this.syncing = this._syncLoop().finally(() => {
      this.syncing = null;
    });
    return this.syncing;
  }

  async _syncLoop() {
    const d = this.data;
    if (!d || d.mode !== 'account') return false;
    try {
      while (d.pending.length) {
        const chunk = d.pending.slice(0, SYNC_CHUNK);
        const fromSeq = d.confirmed.seq + 1;
        const after =
          chunk.length === d.pending.length ? d.current : replay(d.confirmed.state, chunk).state;
        let result = await this.api.sync(d.sessionId, { fromSeq, actions: chunk, clientHash: hashState(after) });
        for (let i = 0; result.status === 'queued' && i < MAX_POLLS; i++) {
          await new Promise((r) => setTimeout(r, POLL_MS));
          result = await this.api.getBatch(result.batchId);
        }
        if (result.status === 'queued') return false; // try again later

        if (result.status === 'done' && result.matches) {
          d.confirmed = { seq: result.seq, state: after };
          d.pending = d.pending.filter((a) => a.seq > result.seq);
        } else if (result.status === 'done') {
          this._rebase(result.session, { batchApplied: true, appliedUpTo: result.seq });
          this._changed();
        } else {
          // Conflict (out of sync) or failed: the server state is the truth.
          this._rebase(result.session, { batchApplied: false });
          this._changed();
        }
        this.persist();
      }
      this.lastSyncError = null;
      return true;
    } catch (err) {
      this.lastSyncError = err;
      const status = err && err.response && err.response.status;
      if (status === 409) {
        // Our session was archived (new game / restore on another device).
        const server = await this.api.getSession().catch(() => null);
        if (server) {
          this._fromServer(server, d.userId);
          this.persist();
          this._changed();
        }
      }
      return false;
    }
  }
}
